ALLOWED_CATEGORIES = {'malaria', 'climate', 'operations', 'other'}
DISTRICTS = {'LGA-001', 'LGA-002'}

def validate_result(x):
    errors = []
    if x.get('category') not in ALLOWED_CATEGORIES: errors.append('invalid category')
    if not isinstance(x.get('summary'), str): errors.append('summary must be text')
    if not set(x.get('evidence_ids', [])).issubset({'SRC-1','SRC-2'}): errors.append('unknown evidence id')
    if x.get('district_id') not in DISTRICTS: errors.append('unknown district')
    return {'valid': not errors, 'errors': errors}
